    targetDir,
    targetRevision: revision,
    outDir,
    requested: n,
    planted: planted.length,
    sitesConsidered: candidates.length,
    rejectedBySeparation,
    rejectedByCheck,
    perEntryCounts,
    sites: issues.map(issue => ({ id: issue.id, entryId: planted.find(site => site.finalLine === issue.lines[0] && site.file === issue.file).entryId, file: issue.file, line: issue.lines[0] })),
  }
